partial class Program {
 static SeasideMainMenuPatch.CodeEntryView CodeSkin=>(SeasideMainMenuPatch.CodeEntryView)typeof(SeasideMainMenuPatch).GetField("codeEntryView",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).GetValue(null);
