  EnterCodeManagerPatch.vServerOnlyCheckBox=new GameObject("ServerOnly").AddComponent<Checkbox>();EnterCodeManagerPatch.vServerOnlyCheckBox.transform.SetParent(panel.transform,false);EnterCodeManagerPatch.vServerOnlyCheckBox.gameObject.AddComponent<BoxCollider2D>();EnterCodeManagerPatch.vServerOnlyCheckBox.gameObject.AddComponent<SpriteRenderer>();T("OldCheckboxLabel",EnterCodeManagerPatch.vServerOnlyCheckBox.transform);
  panel.SetActive(false);x.code.OnClick.AddListener((Action)(()=>{panel.SetActive(true);Call("CodeEntryOpened",code);}));
