 }
 static void CodeEntryTests(){
  var config=BepInEx.Paths.ConfigPath;OnlineAssetFolder();
  Test("code skin does not open before native handoff",()=>{var x=CodeFixture(false);Call("CodeEntryOpened",x.code);Check(CodeSkin==null);x.view.Dispose();});
  Test("code skin reuses the exact native field and event objects",()=>{var x=CodeFixture();var f=x.code.enterCodeField;var change=f.OnChange;var join=x.code.joinGamePassiveButton.OnClick;for(int i=0;i<50;i++)CodeSkin.Tick();Check(f==x.code.enterCodeField&&f.OnChange==change&&x.code.joinGamePassiveButton.OnClick==join);Call("CloseCodeEntry");x.view.Dispose();});
  Test("native field focus and text-change callbacks survive presentation",()=>{var x=CodeFixture();int changed=0;x.code.enterCodeField.OnChange.AddListener(()=>changed++);x.code.enterCodeField.GiveFocus();x.code.enterCodeField.SetText("ABCDEF");CodeSkin.Tick();Check(x.code.enterCodeField.hasFocus&&x.code.enterCodeField.text=="ABCDEF"&&changed==1&&x.code.enterCodeField.AllowPaste);Call("CloseCodeEntry");x.view.Dispose();});
  Test("native enter callback survives repeated layout and teardown",()=>{var x=CodeFixture();int n=0;x.code.enterCodeField.OnEnter.AddListener(()=>n++);CodeSkin.Tick();x.code.enterCodeField.OnEnter.Invoke();Call("CloseCodeEntry");x.code.enterCodeField.OnEnter.Invoke();Check(n==2);x.view.Dispose();});
  Test("join enable/disable is controlled exclusively by native collider state",()=>{var x=CodeFixture();var c=x.code.joinGamePassiveButton.GetComponent<BoxCollider2D>();c.enabled=false;CodeSkin.Tick();Check(!c.enabled);c.enabled=true;CodeSkin.Tick();Check(c.enabled);Call("CloseCodeEntry");x.view.Dispose();});
  Test("skin never adds a join event or double invokes the native handler",()=>{var x=CodeFixture();int n=0;x.code.joinGamePassiveButton.OnClick.AddListener(()=>n++);for(int i=0;i<100;i++)CodeSkin.Tick();Check(n==0);x.code.joinGamePassiveButton.OnClick.Invoke();Check(n==1);Call("CloseCodeEntry");x.view.Dispose();});
  Test("host capacity region chat strings remain live native data",()=>{var x=CodeFixture();x.code.hostText.text="Synthetic host";x.code.capacityText.text="7/15";x.code.serverText.text="Europe";x.code.chatText.text="Quick Chat";CodeSkin.Tick();Check(x.code.hostText.text=="Synthetic host"&&x.code.capacityText.text=="7/15"&&x.code.serverText.text=="Europe"&&x.code.chatText.text=="Quick Chat");Call("CloseCodeEntry");x.view.Dispose();});
  Test("field-container visibility remains under native lookup control",()=>{var x=CodeFixture();x.fields.SetActive(false);CodeSkin.Tick();Check(!x.code.hostText.gameObject.activeInHierarchy&&!x.code.joinGamePassiveButton.gameObject.activeInHierarchy);x.fields.SetActive(true);CodeSkin.Tick();Check(x.code.hostText.gameObject.activeInHierarchy);Call("CloseCodeEntry");x.view.Dispose();});
  foreach(string id in new[]{"Restore","Download","Unload","Server"})Test("existing Shell auxiliary action remains intact: "+id,()=>{var x=CodeFixture();var b=id=="Restore"?EnterCodeManagerPatch.RestoreButton:id=="Download"?EnterCodeManagerPatch.DownloadButton:id=="Unload"?EnterCodeManagerPatch.UnloadAndJoinButton:EnterCodeManagerPatch.ServerList;var e=b.OnClick;int n=0;e.AddListener(()=>n++);CodeSkin.Tick();Check(b.OnClick==e);b.OnClick.Invoke();Check(n==1);Call("CloseCodeEntry");x.view.Dispose();});
  Test("dropdown stays above the panel without being forced open",()=>{var x=CodeFixture();var drop=EnterCodeManagerPatch.ServerListDrop;Check(!drop.gameObject.activeSelf);drop.gameObject.SetActive(true);CodeSkin.Tick();Check(drop.GetComponent<SpriteRenderer>().sortingOrder==30);Call("CloseCodeEntry");x.view.Dispose();});
  Test("obsolete art is hidden but text box renderers remain native",()=>{var x=CodeFixture();Check(!Obj.Objects.Single(g=>g.name=="ObsoleteCodeArtwork").GetComponent<SpriteRenderer>().enabled&&x.code.enterCodeField.GetComponent<SpriteRenderer>().enabled);Call("CloseCodeEntry");Check(Obj.Objects.Single(g=>g.name=="ObsoleteCodeArtwork").GetComponent<SpriteRenderer>().enabled);x.view.Dispose();});
  Test("background native buttons are blocked and restored",()=>{var x=CodeFixture();var c=x.menu.playButton.GetComponent<BoxCollider2D>();Check(!c.enabled);Call("CloseCodeEntry");Check(c.enabled);x.view.Dispose();});
  Test("native controller state and selection are never replaced",()=>{var x=CodeFixture();var state=new ControllerUiElementsState{MenuName="EnterCode",IsScene=false,CurrentSelection=x.code.BackButton};ControllerManager.Instance.CurrentUiState=state;CodeSkin.Tick();Check(ControllerManager.Instance.CurrentUiState==state&&state.CurrentSelection==x.code.BackButton);Call("CloseCodeEntry");x.view.Dispose();});
  Test("native disable restores transforms without resetting typed text",()=>{var x=CodeFixture(false);var f=x.code.enterCodeField;f.transform.localPosition=new(3,4,5);var p=f.transform.localPosition;var s=f.transform.localScale;Proxy("OnlineCode").OnClick.Invoke();Pump(x.view,30);f.SetText("ABCDEF");Call("CodeEntryClosing",x.code);Near(f.transform.localPosition.x,p.x);Near(f.transform.localPosition.y,p.y);Near(f.transform.localScale.x,s.x);Check(f.text=="ABCDEF");x.view.Dispose();});
  Test("native back event remains unchanged",()=>{var x=CodeFixture();var b=(PassiveButton)x.code.BackButton;int n=0;b.OnClick.AddListener(()=>n++);b.OnClick.Invoke();Check(n==1);Call("CodeEntryClosing",x.code);x.view.Dispose();});
  Test("code return and re-entry never duplicate skins or callbacks",()=>{var x=CodeFixture();for(int i=0;i<15;i++){Call("CodeEntryClosing",x.code);x.code.gameObject.SetActive(false);Call("OnlineMenuReady",x.menu);x.view.ResumeNativePlay();Call("CodeEntryOpened",x.code);Check(CodeSkin==null);x.code.gameObject.SetActive(true);Proxy("OnlineCode").OnClick.Invoke();Pump(x.view,30);Check(CodeSkin!=null&&Obj.Objects.Count(g=>g.name=="ShellSeasideCodeEntry")==1);}Call("CloseCodeEntry");x.view.Dispose();});
  Test("error popup suspends skin and restores native layer ordering",()=>{var x=CodeFixture();var r=x.code.hostText.GetComponent<MeshRenderer>();var popup=new GameObject("Error").AddComponent<GenericPopup>();Call("GenericOpening",popup);CodeSkin.Tick();Check(!CodeSkin.Visible&&r.sortingOrder==0);popup.gameObject.SetActive(false);CodeSkin.Tick();Check(CodeSkin.Visible&&r.sortingOrder==20);Call("CloseCodeEntry");x.view.Dispose();});
  Test("scene departure releases presentation and background input",()=>{var x=CodeFixture();GameScene();Call("TickCodeEntry");Check(CodeSkin==null&&!Obj.Objects.Any(g=>g.name=="ShellSeasideCodeEntry")&&x.menu.playButton.GetComponent<BoxCollider2D>().enabled);x.view.Dispose();});
  Test("unknown native prefab falls back without partially hiding input",()=>{var x=CodeFixture(false);x.code.enterCodeField=null;Proxy("OnlineCode").OnClick.Invoke();Pump(x.view,30);Check(CodeSkin==null&&!Obj.Objects.Any(g=>g.name=="ShellSeasideCodeEntry"));x.view.Dispose();});
  foreach(var size in new[]{(1920,1080),(1024,768),(800,1280),(3440,1440)})Test("all control rectangles remain inside safe art at "+size,()=>{var f=SeasideMenuLayout.Fit(size.Item1,size.Item2);foreach(var r in SeasideCodeEntryLayout.Controls.Values){Check(r.X>=0&&r.Y>=0&&r.X+r.Width<=1672&&r.Y+r.Height<=941);var p=f.ToScreen(r.CenterX,r.CenterY);var a=f.ToArt(p.x,p.y);Near(a.x,r.CenterX);Near(a.y,r.CenterY);}});
  Test("blank artwork contains no input components",()=>{var x=CodeFixture();foreach(var g in Obj.Objects.Where(g=>g.name.StartsWith("CodeEntryArt_")))Check(g.GetComponentsInChildren<Collider2D>(true).Length==0);Call("CloseCodeEntry");x.view.Dispose();});
  Test("corrupt optional image leaves native controls usable",()=>{var folder=OnlineAssetFolder();folder=Path.Combine(BepInEx.Paths.ConfigPath,"TOH-Shell","MainMenu","CodeEntry");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"panel.png"),"broken");var x=CodeFixture();Check(CodeSkin.Visible&&x.code.enterCodeField.GetComponent<Collider2D>().enabled);Call("CloseCodeEntry");x.view.Dispose();});
  Test("oversized image dimensions are rejected",()=>{Check(!SeasideCodeEntryLayout.ValidImageDimensions(4097,100)&&!SeasideCodeEntryLayout.ValidImageDimensions(100,0)&&SeasideCodeEntryLayout.ValidImageDimensions(4096,4096));});
  Test("code skin disposes when native panel disappears unexpectedly",()=>{var x=CodeFixture();x.code.gameObject.SetActive(false);Call("TickCodeEntry");Check(CodeSkin==null);x.view.Dispose();});
  Test("inactive disabled join uses authored collider dimensions",()=>{var x=CodeFixture(false);var b=x.code.joinGamePassiveButton;b.GetComponent<BoxCollider2D>().size=new(4,.7f);b.GetComponent<BoxCollider2D>().enabled=false;x.fields.SetActive(false);Proxy("OnlineCode").OnClick.Invoke();Pump(x.view,30);var root=Obj.Objects.Single(g=>g.name=="ShellSeasideCodeEntry");Near(b.transform.lossyScale.x,root.transform.lossyScale.x*1.1);Near(b.transform.lossyScale.y,root.transform.lossyScale.x*1.1);x.fields.SetActive(true);CodeSkin.Tick();Check(!b.GetComponent<BoxCollider2D>().enabled);Call("CloseCodeEntry");x.view.Dispose();});
  Test("old click and sprite masks are leased and restored",()=>{var x=CodeFixture(false);var mask=new GameObject("OldMask").AddComponent<BoxCollider2D>();var b=x.code.joinGamePassiveButton;b.ClickMask=mask;var r=b.GetComponent<SpriteRenderer>();r.maskInteraction=SpriteMaskInteraction.VisibleInsideMask;Proxy("OnlineCode").OnClick.Invoke();Pump(x.view,30);Check(b.ClickMask==null&&r.maskInteraction==SpriteMaskInteraction.None);Call("CloseCodeEntry");Check(b.ClickMask==mask&&r.maskInteraction==SpriteMaskInteraction.VisibleInsideMask);x.view.Dispose();});
  Test("pooled dropdown options acquire presentation without event changes",()=>{var x=CodeFixture();var drop=EnterCodeManagerPatch.ServerListDrop;drop.gameObject.SetActive(true);var b=new TownOfHost.Templates.SimpleButton(drop.transform,"PooledRegion",new(),Color.white,Color.white,()=>{},"region").Button;var mask=new GameObject("DropdownOldMask").AddComponent<BoxCollider2D>();b.ClickMask=mask;var e=b.OnClick;CodeSkin.Tick();Check(b.ClickMask==null&&b.GetComponent<SpriteRenderer>().sortingOrder==30&&b.OnClick==e);Call("CloseCodeEntry");Check(b.ClickMask==mask&&b.GetComponent<SpriteRenderer>().sortingOrder==0);x.view.Dispose();});
  Test("MOD stamp is visible and original placement restores",()=>{var x=CodeFixture();var stamp=new GameObject("ModStamp").AddComponent<SpriteRenderer>();stamp.transform.position=new(2,3,4);CodeSkin.PositionStamp(stamp);Check(stamp.sortingOrder==8);Call("CloseCodeEntry");Check(stamp.sortingOrder==0);Near(stamp.transform.position.x,2);Near(stamp.transform.position.y,3);x.view.Dispose();});
  Test("optional panel and shared button PNGs replace presentation only",()=>{OnlineAssetFolder();var folder=Path.Combine(BepInEx.Paths.ConfigPath,"TOH-Shell","MainMenu","CodeEntry");Directory.CreateDirectory(folder);OnlineAsset(folder,"panel.png",1170,560);OnlineAsset(folder,"button.png",440,78);ImageConversion.Success=true;var x=CodeFixture();Check(!Obj.Objects.Single(g=>g.name=="CodeEntryPanel").GetComponent<SpriteRenderer>().enabled);var a=Obj.Objects.Single(g=>g.name=="CodeEntryArt_Back").GetComponent<SpriteRenderer>();var b=Obj.Objects.Single(g=>g.name=="CodeEntryArt_Join").GetComponent<SpriteRenderer>();Check(a.enabled&&b.enabled&&a.sprite==b.sprite);x.code.joinGamePassiveButton.GetComponent<BoxCollider2D>().enabled=false;CodeSkin.Tick();Near(b.color.r,.5);Check(x.code.joinGamePassiveButton.OnClick.Calls==0);Call("CloseCodeEntry");x.view.Dispose();ImageConversion.Success=false;OnlineAssetFolder();});
  Test("per-button PNG override leaves other button images shared",()=>{OnlineAssetFolder();var folder=Path.Combine(BepInEx.Paths.ConfigPath,"TOH-Shell","MainMenu","CodeEntry");Directory.CreateDirectory(folder);OnlineAsset(folder,"button.png",440,78);OnlineAsset(folder,"button-back.png",195,60);ImageConversion.Success=true;var x=CodeFixture();var back=Obj.Objects.Single(g=>g.name=="CodeEntryArt_Back").GetComponent<SpriteRenderer>();var join=Obj.Objects.Single(g=>g.name=="CodeEntryArt_Join").GetComponent<SpriteRenderer>();var restore=Obj.Objects.Single(g=>g.name=="CodeEntryArt_Restore").GetComponent<SpriteRenderer>();Check(back.sprite!=join.sprite&&join.sprite==restore.sprite);Call("CloseCodeEntry");x.view.Dispose();ImageConversion.Success=false;OnlineAssetFolder();});
  Test("custom button artwork follows native hover and disabled state",()=>{OnlineAssetFolder();var folder=Path.Combine(BepInEx.Paths.ConfigPath,"TOH-Shell","MainMenu","CodeEntry");Directory.CreateDirectory(folder);OnlineAsset(folder,"button.png",440,78);ImageConversion.Success=true;var x=CodeFixture(false);var highlight=new GameObject("NativeJoinHighlight");highlight.transform.SetParent(x.code.joinGamePassiveButton.transform,false);highlight.SetActive(false);x.code.joinGamePassiveButton.activeSprites=highlight;Proxy("OnlineCode").OnClick.Invoke();Pump(x.view,30);var r=Obj.Objects.Single(g=>g.name=="CodeEntryArt_Join").GetComponent<SpriteRenderer>();Near(r.color.r,1);highlight.SetActive(true);CodeSkin.Tick();Near(r.color.r,.9);x.code.joinGamePassiveButton.GetComponent<BoxCollider2D>().enabled=false;CodeSkin.Tick();Near(r.color.r,.5);Call("CloseCodeEntry");x.view.Dispose();ImageConversion.Success=false;OnlineAssetFolder();});
  Test("Shell and official version labels remain distinct and live",()=>{var x=CodeFixture();var native=Obj.FindObjectOfType<VersionShower>();native.text.text="v19s (build num: 7489)";TownOfHost.Main.PluginShowVersion="2.2.2";CodeSkin.Tick();Check(Text("CodeEntryVersion").text=="TOH-Shell v2.2.2"&&Text("CodeEntryGameVersion").text==native.text.text);Call("CloseCodeEntry");x.view.Dispose();});
  BepInEx.Paths.ConfigPath=config;
  ImageConversion.Success=false;
 }
